/* Figure 6 learning redraw: SMBus 3.3 p.18; numeric limits from Table 2.
   Original specification © SMIF, Inc. Independently drawn SVG, not to scale. */
function mountFigure6(container,onSelect){
const measures=[
{id:'tBUF',a:188.33,b:257.67,y:341,ly:375,from:'STOP: SMBDAT가 VIH,min을 통과',to:'다음 START: SMBDAT가 VIH,min 아래로 하강',tip:'STOP과 START 사이에 양 선이 HIGH로 유지되는 버스 해제 시간.'},
{id:'tHD:STA',a:280.33,b:315.67,y:200,ly:230,from:'START: SMBDAT가 VIL,max 아래로 하강',to:'SMBCLK가 VIH,min 아래로 하강',tip:'START를 만든 뒤 첫 clock LOW를 시작하기 전까지 확보하는 시간.'},
{id:'tLOW',a:338.33,b:429.67,y:45,ly:27,from:'SMBCLK 하강이 VIL,max를 통과',to:'다음 SMBCLK 상승이 VIL,max를 통과',tip:'유효 LOW 임계값 사이의 clock LOW 폭.'},
{id:'tR',a:424,b:458,y:45,ly:73,lx:486,from:'상승 에지: VIL,max − 0.15 V = 0.65 V',to:'상승 에지: VIH,min + 0.15 V = 1.50 V',tip:'Note 7의 마진을 적용한다. 30–70% VDD 측정이 아니다.'},
{id:'tHD:DAT',a:508.33,b:535.33,y:200,ly:230,lx:487,from:'SMBCLK 하강이 VIL,max를 통과',to:'SMBDAT가 이전 유효 레벨을 벗어나기 시작',tip:'송신 장치가 보장한다. 0 ns여도 클럭이 LOW가 되기 전에 데이터가 바뀌면 안 된다.'},
{id:'tHIGH',a:602.33,b:653.33,y:200,ly:230,from:'SMBCLK 상승이 VIH,min을 통과',to:'다음 하강이 VIH,min을 통과',tip:'HIGH 구간에서 데이터가 안정되어야 한다. 상한은 모든 클래스에서 50 µs.'},
{id:'tF',a:648,b:680,y:45,ly:27,lx:702,from:'하강 에지: VIH,min + 0.15 V = 1.50 V',to:'하강 에지: VIL,max − 0.15 V = 0.65 V',tip:'tR과 반대 방향. Table 2 Note 7의 ±150 mV 측정 마진을 사용한다.'},
{id:'tSU:DAT',a:721.67,b:751.67,y:200,ly:230,lx:767,from:'SMBDAT가 새 유효 레벨에 도달',to:'SMBCLK 상승이 VIL,max에 도달',tip:'다음 clock 상승 전까지 데이터를 안정시켜야 하는 시간.'},
{id:'tSU:STA',a:886.67,b:913.67,y:200,ly:230,lx:925,from:'SMBCLK 상승이 VIH,min을 통과',to:'repeated START: SMBDAT가 VIH,min 아래로 하강',tip:'STOP을 넣지 않고 새 START를 만드는 조건의 setup 시간.'},
{id:'tSU:STO',a:1285,b:1317.33,y:200,ly:230,lx:1295,from:'SMBCLK 상승이 VIH,min을 통과',to:'STOP: SMBDAT 상승이 VIL,max를 통과',tip:'클럭이 HIGH가 된 다음 데이터를 HIGH로 풀어 STOP을 만든다.'}
];
let active='tLOW',speed=0;
const T=(x,y,s,color='#aec0d3',size=14,anchor='start')=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" text-anchor="${anchor}" font-family="Arial, sans-serif">${s}</text>`;
const wave=(d,col,dash='')=>`<path d="${d}" fill="none" stroke="${col}" stroke-width="2.5" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
let drawing=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1400 420" aria-label="SMBus 3.3 Figure 6 전체 타이밍 파형. 각 파라미터에 포인터를 올리거나 Enter를 누르면 설명 표시." role="group"><defs><marker id="f6arrow" markerWidth="7" markerHeight="7" refX="3.5" refY="3.5" orient="auto-start-reverse"><path d="M0 0 L7 3.5 L0 7" fill="#ffc775"/></marker></defs><rect width="1400" height="420" fill="#101b27"/>`;
// STOP, START, repeated START, STOP event bands.
for(const [x,color,label] of [[188,'#ff889a','P'],[268,'#7adeb4','S'],[924,'#7adeb4','Sr'],[1325,'#ff889a','P']])drawing+=`<rect x="${x-21}" y="83" width="42" height="245" fill="${color}" opacity=".13"/>`+T(x,403,label,color,18,'middle');
drawing+=T(15,118,'SMBCLK','#7de0bb',17)+T(15,278,'SMBDAT','#8cb6ff',17);
for(const [y,l] of [[110,'VIH,min'],[150,'VIL,max'],[270,'VIH,min'],[310,'VIL,max']])drawing+=`<path d="M140 ${y} H1370" stroke="#708295" stroke-dasharray="6 5" stroke-width="1"/>`+T(15,y+20,l,'#91a3b8',11);
drawing+=wave('M140 100 H310 L344 160 H424 L458 100 H480 L514 160 H574 L608 100 H648 L680 160 H746','#7de0bb');
drawing+=wave('M746 160 L780 100 H850','#7de0bb','6 5');
drawing+=wave('M746 160 H860 L892 100 H952 L984 160 H1080 L1114 100 H1150 L1184 160 H1250 L1292 100 H1370','#7de0bb');
drawing+=wave('M140 320 H160 L194 260 H252 L286 320 H370 L402 260 H530 L562 320 H690 L728 260','#8cb6ff');
drawing+=wave('M286 320 H530 L562 260 H690 L728 320','#8cb6ff');
drawing+=wave('M728 260 H800','#8cb6ff','6 5')+wave('M728 320 H800 L832 260 H908 L942 320 H1010 L1042 260 H1086 L1118 320 H1232 L1264 320 H1312 L1344 260 H1370','#8cb6ff');
drawing+=wave('M942 320 H1086 L1118 260 H1232 L1264 320','#8cb6ff');
for(const m of measures){let center=m.lx??(m.a+m.b)/2;let labelW=m.id.length*9+22;
drawing+=`<g class="f6-target" data-measure="${m.id}" tabindex="0" role="button" aria-label="${m.id} 설명과 속도별 스펙 보기" aria-pressed="false"><title>${m.id} — 포인터 / 터치 / Enter로 설명</title><rect class="f6-band" x="${m.a}" y="90" width="${Math.max(m.b-m.a,5)}" height="240" fill="#ffc775" opacity="0"/><path d="M${m.a} ${m.y<100?m.y:95} V${m.y>300?345:m.y<100?165:320} M${m.b} ${m.y<100?m.y:95} V${m.y>300?345:m.y<100?165:320}" stroke="#ffc775" stroke-width="1" stroke-dasharray="3 4" opacity=".35"/><path d="M${m.a} ${m.y} H${m.b}" stroke="#ffc775" stroke-width="1.4" marker-start="url(#f6arrow)" marker-end="url(#f6arrow)"/><rect x="${Math.min(center-labelW/2,m.a-10)}" y="${Math.min(m.ly-24,m.y-14)}" width="${Math.max(center+labelW/2,m.b+10)-Math.min(center-labelW/2,m.a-10)}" height="${Math.max(m.ly+13,m.y+14)-Math.min(m.ly-24,m.y-14)}" fill="transparent" pointer-events="all"/><rect class="f6-label-bg" x="${center-labelW/2}" y="${m.ly-19}" width="${labelW}" height="30" rx="5" fill="#223347" stroke="#53677d"/>${T(center,m.ly+2,m.id,'#ffce86',15,'middle')}${['tR','tF'].includes(m.id)?T(center,m.ly+22,'Note 7','#a6b7ca',10,'middle'):''}</g>`;}
drawing+=T(700,403,'Figure 6 · SMBus timing measurements · learning redraw','#92a7bd',12,'middle')+'</svg>';
container.innerHTML=`<section class="lab figure6-lab"><div class="lab-title">스펙 원문 파형에서 찾아보기 <span>FIGURE 6 · p.18</span></div><div class="lab-body"><p class="hint">이름이나 노란 측정 화살표에 <b>마우스를 올리세요.</b> 휴대폰에서는 <b>터치</b>하면 설명이 유지됩니다. 좌우로 밀어 전체 파형을 볼 수 있습니다.</p><div class="toolbar"><label>비교 기준<select id="f6-speed"><option>100 kHz</option><option>400 kHz</option><option>1 MHz</option></select></label><label class="zoom-label">파형 확대 <output id="f6-zoom-value">100%</output><input id="f6-zoom" type="range" min="100" max="200" step="25" value="100" aria-label="원문 파형 확대 비율"></label><a class="btn" href="${SMB.PDF}#page=18" target="_blank" rel="noopener">원문 그림 ↗</a></div><div class="figure6-wrap"><div id="f6-scroll" tabindex="0" aria-label="전체 타이밍 파형, 좌우 스크롤 가능"><div id="f6-canvas">${drawing}</div></div><div id="f6-tooltip" role="tooltip" hidden></div></div><div class="f6-pills" aria-label="파라미터 바로 선택">${measures.map(m=>`<button class="btn" data-pick="${m.id}">${m.id}</button>`).join('')}</div><section id="f6-detail" class="f6-detail" aria-live="polite"></section><p class="hint">원문 Figure 6의 순서·측정 관계를 SVG로 재구성했습니다. 시간축은 비례하지 않습니다. 교차된 두 DAT 선은 가능한 데이터 전이 방향이며 두 개의 물리 신호가 아닙니다. tR/tF는 Note 7의 마진을 적용합니다.</p><button class="btn" id="f6-to-lab">선택 항목을 아래 수치 실험에서 조절 ↓</button></div></section>`;
const root=container;const find=s=>root.querySelector(s);function show(id){active=id;const m=measures.find(m=>m.id===id),p=SMB.timing.find(p=>p.id===id);root.querySelectorAll('[data-measure]').forEach(g=>{const yes=g.dataset.measure===id;g.classList.toggle('selected',yes);g.setAttribute('aria-pressed',yes);g.querySelector('.f6-band').setAttribute('opacity',yes?'.13':'0');});root.querySelectorAll('[data-pick]').forEach(b=>{b.classList.toggle('primary',b.dataset.pick===id);b.setAttribute('aria-pressed',b.dataset.pick===id);});find('#f6-detail').innerHTML=`<div><div class="eyebrow">SELECTED PARAMETER</div><h3><code>${id}</code> · ${p.name}</h3><p>${m.tip}</p><div class="f6-endpoints"><div><b>A · 측정 시작</b><span>${m.from}</span></div><div><b>B · 측정 끝</b><span>${m.to}</span></div></div></div><div>${table(['클래스','최소','최대'],['100 kHz','400 kHz','1 MHz'].map((s,i)=>[`${i===speed?'▶ ':''}${s}`,p.min?.[i]==null?'—':p.min[i]+' '+p.unit,p.max?.[i]==null?'—':p.max[i]+' '+p.unit]))}<small>—: 표에 해당 한계 없음 · Table 2 pp.18–20</small></div>`;}
function tooltip(e,id){if(e.pointerType==='touch')return;const p=SMB.timing.find(p=>p.id===id),box=find('.figure6-wrap').getBoundingClientRect(),tip=find('#f6-tooltip');tip.innerHTML=`<b>${id}</b> · ${['100 kHz','400 kHz','1 MHz'][speed]}<br>최소 ${p.min?.[speed]??'—'} / 최대 ${p.max?.[speed]??'—'} ${p.unit}<br><small>아래 설명에서 측정 시작·끝 확인</small>`;tip.hidden=false;tip.style.left=Math.max(8,Math.min((e.clientX||box.left)-box.left+12,box.width-260))+'px';tip.style.top=Math.max(8,(e.clientY||box.top)-box.top-86)+'px';}
root.querySelectorAll('[data-measure]').forEach(g=>{const id=g.dataset.measure;g.onpointerenter=e=>{show(id);tooltip(e,id);};g.onpointermove=e=>tooltip(e,id);g.onpointerleave=()=>find('#f6-tooltip').hidden=true;g.onfocus=()=>show(id);g.onclick=()=>{show(id);find('#f6-tooltip').hidden=true;};g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(id);}if(e.key==='Escape')find('#f6-tooltip').hidden=true;};});
root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{show(b.dataset.pick);const m=measures.find(x=>x.id===active),scroll=find('#f6-scroll'),canvas=find('#f6-canvas');scroll.scrollLeft=Math.max(0,(m.a/1400)*canvas.getBoundingClientRect().width-scroll.clientWidth/2);});
find('#f6-speed').onchange=e=>{speed=e.target.selectedIndex;find('#f6-tooltip').hidden=true;show(active);};find('#f6-zoom').oninput=e=>{const zoom=+e.target.value;find('#f6-zoom-value').textContent=zoom+'%';find('#f6-canvas').style.width=zoom+'%';};find('#f6-to-lab').onclick=()=>onSelect(active,speed);find('#f6-scroll').onscroll=()=>find('#f6-tooltip').hidden=true;show(active);
}
